27 |   const path = join(root, FILE)
28 |   const errors: Issue[] = []
29 |   const warnings: Issue[] = []
30 | 
31 |   if (!existsSync(path)) {
32 |     return { found: false, config: {}, docsDir: 'docs', errors, warnings }
33 |   }
34 | 
35 |   let parsed: unknown
36 |   try {
37 |     parsed = JSON.parse(readFileSync(path, 'utf8'))
38 |   } catch (error) {
39 |     errors.push({
