41 |       message: `is not valid JSON (${(error as Error).message}). DocuGate ignores it and reads docs/.`,
42 |     })
43 |     return { found: true, config: {}, docsDir: 'docs', errors, warnings }
44 |   }
45 | 
46 |   if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
47 |     errors.push({ file: FILE, message: 'must be a JSON object.' })
48 |     return { found: true, config: {}, docsDir: 'docs', errors, warnings }
49 |   }
