140 |   } catch (error) {
141 |     // A .json URL that actually serves YAML, or the other way round.
142 |     try {
143 |       doc = source.yaml ? JSON.parse(source.text) : parseYaml(source.text, { maxAliasCount: 100 })
144 |     } catch {
145 |       throw new Error(`${opts.from} is neither valid JSON nor YAML: ${(error as Error).message}`)
146 |     }
147 |   }
