149 |   if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
150 |     throw new Error(`${opts.from} is not an OpenAPI document.`)
151 |   }
152 |   const spec = doc as Record<string, unknown>
153 | 
154 |   if (typeof spec.swagger === 'string') {
155 |     throw new Error(
156 |       `${opts.from} is Swagger ${spec.swagger}. DocuGate reads OpenAPI 3.0 and 3.1; convert it first, for example with swagger2openapi.`,
