  // import.meta.url points at dist/tour-server.js at runtime, so go up one level.
  const pkgRoot = fileURLToPath(new URL('..', import.meta.url))
  const pillPath = join(pkgRoot, 'pill', 'dist', 'pill.js')
  if (!existsSync(pillPath)) {
