const { startTourServer } = require('./dist/tour-server.js');
const { cpSync, mkdtempSync } = require('node:fs');
const { tmpdir } = require('node:os');
const http = require('node:http');

async function run() {
  const dir = mkdtempSync(require('node:path').join(tmpdir(), 'docugate-server-'));
  require('node:fs').cpSync('test/fixtures/tour-check', dir, { recursive: true });
  const server = await startTourServer(dir, 0);
  console.log('server started on port', server.port);

  return new Promise((resolve, reject) => {
    const received = [];
    const req = http.get('http://127.0.0.1:' + server.port + '/events', { headers: { host: 'localhost' } }, (res) => {
      res.on('data', (chunk) => {
        received.push(chunk.toString());
        if (received.some(c => c.includes('change'))) {
          req.destroy();
          setTimeout(() => { server.close(); resolve(); }, 10);
        }
      });
      res.on('error', (e) => { if (e.code !== 'ECONNRESET') reject(e); });
      setTimeout(() => {
        require('node:fs').writeFileSync(
          dir + '/.docugate/tour/home.md',
          '---\nroute: /\ntitle: Home\n---\n\n## Hero\ntarget: t\ncode: x.ts\n\nUpdated.\n'
        );
      }, 50);
      setTimeout(() => reject(new Error('SSE timeout')), 3000);
    });
    req.on('error', (e) => { if (e.code !== 'ECONNRESET') reject(e); });
  });
}
run().then(() => { console.log('done'); process.exit(0); }).catch(e => { console.error(e.message); process.exit(1); });
